#!/usr/bin/env python3
"""High-intent refinance posts, November 2026 (20 posts across this file and
refinance_intent_posts_b.py).

Each one answers a specific search people make just before or during a
refinance, and none repeats the existing refix, break-fee, cashback, top-up,
separation, rental-portfolio or "new bank said no" posts. Those are linked.

Run:  python3 generate_local_intent_blogs.py refinance_intent_posts
"""

from intent_post_kit import REL_REFI, RBNZ_LVR, callout, link, ol, post, table


def R(*a, extra=(), **k):
    return post(*a, service="Refinance", label="Refinance", refi_form=True,
                related=REL_REFI + list(extra), **k)


